//! 🛬️ Typed image native construction with cumulative caller admission.
use semio_framework_value::{ValueError,ValueRefusalKind};
use crate::standards::v1::subsets::image::schema::snapshot::{SemioImageSnapshot,SemioImageFrame,SemioImageMetadataEntry,SemioColorspace,STDIO_SEMIOIMAGE_DOCUMENT_SCHEMA};
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};

fn length(reader:&mut store::ByteReader<'_>)->Result<usize,ValueError>{usize::try_from(reader.read_varint_u64().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?).map_err(|_|ValueError::new(ValueRefusalKind::WorkLimit,"image native length exceeds address space"))}
fn octets<'a>(reader:&mut store::ByteReader<'a>)->Result<&'a[u8],ValueError>{let count=length(reader)?;reader.read_bytes(count).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))}
fn text(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{let value=control.borrow_text(octets(reader)?)?;control.copy_text(value)}
fn rows(count:usize,limits:SqliteDatabaseLimits)->Result<(),ValueError>{if count>limits.max_rows{Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"image native entities exceed caller row limit"))}else{Ok(())}}

/// 🖼️ Reads each named image field without delegating ownership to an uncontrolled codec.
pub(crate) fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<SemioImageSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::image::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio Image native input exceeds file limit"))}
 control.allocation_stage_native(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let native_before=native_control.owned_bytes();let result=native_control.scoped_maximum(native_before.checked_add(remaining).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"native snapshot allowance overflow"))?,|native_control|{
  let result=(||->Result<SemioImageSnapshot,ValueError>{let result=match payload{
   store::io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIOIMAGE_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;binary(body,native_control,limits)?},
   store::io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIOIMAGE_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,native_control,limits)?}
  };let result=crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();result});(result,native_control.owned_bytes().saturating_sub(native_before))
 })?
}

pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioImageSnapshot,ValueError>{
 crate::standards::v1::subsets::image::io::sqlite::snapshot::admit_binary(body,control,limits)?;
 let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported image native format"));}
 let schema=text(&mut reader,control)?;let width=reader.read_u32_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let height=reader.read_u32_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let colorspace=crate::standards::v1::subsets::image::io::binary::snapshot::colorspace_from_tag(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let bit_depth=reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;
 let icc=match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>None,1=>Some(control.copy_bytes(octets(&mut reader)?)?),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid image native ICC presence"))};
 let frame_count=length(&mut reader)?;rows(frame_count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native entity overflow"))?,limits)?;let mut frames=control.allocate_vec::<SemioImageFrame>(frame_count)?;control.begin_stage(frame_count)?;
 for _ in 0..frame_count{let delay_ms=reader.read_u32_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;let rgba8=control.copy_bytes(octets(&mut reader)?)?;frames.push(SemioImageFrame{delay_ms,rgba8});control.step()?;}control.checkpoint()?;
 let metadata_count=length(&mut reader)?;rows(metadata_count.checked_add(frame_count).and_then(|v|v.checked_add(1)).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native entity overflow"))?,limits)?;let mut metadata=control.allocate_vec::<SemioImageMetadataEntry>(metadata_count)?;control.begin_stage(metadata_count)?;
 for _ in 0..metadata_count{let key=text(&mut reader,control)?;let value=text(&mut reader,control)?;metadata.push(SemioImageMetadataEntry{key,value});control.step()?;}control.checkpoint()?;
 if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native trailing bytes"));}Ok(SemioImageSnapshot{schema,width,height,colorspace,bit_depth,icc,frames,metadata})
}

#[derive(Clone)]
pub(super)struct Items<'a>{remaining:&'a str}
impl<'a> Items<'a>{
 pub(super)fn new(value:&'a str)->Result<Self,ValueError>{let value=value.trim();Ok(Self{remaining:value.strip_prefix('[').and_then(|s|s.strip_suffix(']')).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native list requires brackets"))?})}
 pub(super)fn next(&mut self,control:&mut NativeDecodeControl<'_>)->Result<Option<&'a str>,ValueError>{
 if self.remaining.is_empty(){return Ok(None)}let mut depth=0usize;let mut end=self.remaining.len();
 for(index,byte)in self.remaining.bytes().enumerate(){if index%256==0{control.checkpoint()?;}match byte{b'['=>{depth+=1;if depth>2{return Err(ValueError::new(ValueRefusalKind::DepthLimit,"image native list depth exceeds field shape"));}},b']'=>{depth=depth.checked_sub(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native unmatched bracket"))?;},b',' if depth==0=>{end=index;break;},_=>{}}}
 if depth!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native unmatched bracket"));}let value=self.remaining[..end].trim();self.remaining=if end<self.remaining.len(){&self.remaining[end+1..]}else{""};if value.is_empty(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native empty list element"));}Ok(Some(value))
 }
 pub(super)fn count(&self,control:&mut NativeDecodeControl<'_>,maximum:usize)->Result<usize,ValueError>{let mut items=self.clone();let mut count=0usize;while items.next(control)?.is_some(){count=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native list count overflow"))?;if count>maximum{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"image native entities exceed caller row limit"));}}Ok(count)}
}
pub(super)fn pair<'a>(value:&'a str,control:&mut NativeDecodeControl<'_>)->Result<(&'a str,&'a str),ValueError>{let inner=value.trim().strip_prefix('[').and_then(|s|s.strip_suffix(']')).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native pair requires brackets"))?;let mut delimiter=None;for(index,byte)in inner.bytes().enumerate(){if index%256==0{control.checkpoint()?;}match byte{b','=>{if delimiter.replace(index).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native pair has extra fields"));}},b'['|b']'=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native pair contains nested fields")),_=>{}}}let index=delimiter.ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native pair is missing a field"))?;Ok((inner[..index].trim(),inner[index+1..].trim()))}
fn hex(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,ValueError>{
 if !value.len().is_multiple_of(2){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"image native odd hex length"));}
 control.scoped_stage(|control|{let mut out=control.allocate_vec::<u8>(value.len()/2)?;control.begin_stage(value.len()/2)?;for chunk in value.as_bytes().chunks_exact(2){let digit=|v:u8|match v{b'0'..=b'9'=>Ok(v-b'0'),b'a'..=b'f'=>Ok(v-b'a'+10),b'A'..=b'F'=>Ok(v-b'A'+10),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid image native hexadecimal"))};out.push((digit(chunk[0])?<<4)|digit(chunk[1])?);control.step()?;}control.checkpoint()?;Ok(out)})
}
fn hex_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<String,ValueError>{let bytes=hex(value,control)?;control.borrow_text(&bytes)?;String::from_utf8(bytes).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid image native UTF-8"))}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioImageSnapshot,ValueError>{
 crate::standards::v1::subsets::image::io::sqlite::snapshot::admit_document(body,control,limits)?;
 let mut fields:[Option<&str>;8]=[None;8];for line in body.lines(){control.step()?;let line=line.trim();if line.is_empty(){continue}let(name,value)=line.split_once('=').ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native line requires named field"))?;let index=match name{"schema"=>0,"width"=>1,"height"=>2,"colorspace"=>3,"bitDepth"=>4,"icc"=>5,"frames"=>6,"metadata"=>7,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown image native field"))};if fields[index].replace(value).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate image native field"));}}
 let schema=hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native schema field is missing"))?,control)?;let width=crate::standards::v1::subsets::mesh::io::text::snapshot::parse_u32(fields[1].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native width field is missing"))?).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let height=crate::standards::v1::subsets::mesh::io::text::snapshot::parse_u32(fields[2].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"image native height field is missing"))?).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let colorspace=match fields[3]{Some("r")=>SemioColorspace::Rgb,Some("a")=>SemioColorspace::Rgba,Some("g")=>SemioColorspace::Grayscale,Some("y")=>SemioColorspace::GrayscaleAlpha,Some("i")=>SemioColorspace::Indexed,Some(_)=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid image native colorspace")),None=>SemioColorspace::default()};let bit_depth=match fields[4]{Some(value)=>crate::standards::v1::subsets::image::io::text::snapshot::parse_u8(value).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?,None=>0};
 let icc=match fields[5]{None|Some("[0]")=>None,Some(value)=>{let(tag,value)=pair(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid image native ICC presence"));}Some(hex(value,control)?)}};
 let mut frame_items=Items::new(fields[6].unwrap_or("[]"))?;let frame_count=frame_items.count(control,limits.max_rows)?;rows(frame_count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native entity overflow"))?,limits)?;let mut frames=control.allocate_vec::<SemioImageFrame>(frame_count)?;control.begin_stage(frame_count)?;
 while let Some(value)=frame_items.next(control)?{let(delay,rgba)=pair(value,control)?;let delay_ms=crate::standards::v1::subsets::mesh::io::text::snapshot::parse_u32(delay).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error))?;let rgba8=hex(rgba,control)?;frames.push(SemioImageFrame{delay_ms,rgba8});control.step()?;}control.checkpoint()?;
 let mut metadata_items=Items::new(fields[7].unwrap_or("[]"))?;let metadata_count=metadata_items.count(control,limits.max_rows)?;rows(frame_count.checked_add(metadata_count).and_then(|v|v.checked_add(1)).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"image native entity overflow"))?,limits)?;let mut metadata=control.allocate_vec::<SemioImageMetadataEntry>(metadata_count)?;control.begin_stage(metadata_count)?;
 while let Some(value)=metadata_items.next(control)?{let(key,value)=pair(value,control)?;let key=hex_text(key,control)?;let value=hex_text(value,control)?;metadata.push(SemioImageMetadataEntry{key,value});control.step()?;}control.checkpoint()?;Ok(SemioImageSnapshot{schema,width,height,colorspace,bit_depth,icc,frames,metadata})
}
